import 'package:flutter/material.dart';
import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:firebase_auth/firebase_auth.dart';
import 'package:sehatak/core/constants/app_colors.dart';
import 'package:sehatak/core/localization/app_strings.dart';
import 'package:sehatak/presentation/screens/advertisements/ad_management_screen.dart';
import 'package:sehatak/core/models/ad_model.dart';

class AdminDashboard extends StatefulWidget { const AdminDashboard({super.key}); @override State<AdminDashboard> createState()=>_AdminDashboardState(); }
class _AdminDashboardState extends State<AdminDashboard> with SingleTickerProviderStateMixin {
 String _t(String value) => AppStrings.of(context).translate(value);
 late TabController _tabController; int _totalUsers=0,_totalProviders=0,_totalBookings=0,_totalRevenue=0,_pendingAds=0;
 @override void initState(){super.initState();_tabController=TabController(length:4,vsync:this);_loadStats();}
 Future<void> _loadStats() async {try{final users=await FirebaseFirestore.instance.collection('users').get();final providers=await Future.wait([FirebaseFirestore.instance.collection('doctors').get(),FirebaseFirestore.instance.collection('pharmacies').get(),FirebaseFirestore.instance.collection('labs').get(),FirebaseFirestore.instance.collection('hospitals').get()]);final bookings=await FirebaseFirestore.instance.collection('bookings').get();final ads=await FirebaseFirestore.instance.collection('advertisements').where('status',isEqualTo:'pending').get();if(!mounted)return;setState((){_totalUsers=users.size;_totalProviders=providers.fold<int>(0,(s,q)=>s+q.size);_totalBookings=bookings.size;_totalRevenue=bookings.docs.fold<int>(0,(s,d)=>s+((d.data()['amount'] as num?)?.toInt()??0));_pendingAds=ads.size;});}catch(e){debugPrint('Error loading stats: $e');}}
 @override Widget build(BuildContext context){return Scaffold(appBar:AppBar(title:Text(_t('لوحة تحكم المشرف')),actions:[IconButton(onPressed:_loadStats,icon:const Icon(Icons.refresh)),IconButton(onPressed:()=>FirebaseAuth.instance.signOut(),icon:const Icon(Icons.logout))]),body:Column(children:[Container(color:AppColors.primary,padding:const EdgeInsets.all(12),child:Row(children:[_stat(_t('المستخدمين'),'$_totalUsers',Icons.people),_stat(_t('المقدمين'),'$_totalProviders',Icons.business),_stat(_t('الحجوزات'),'$_totalBookings',Icons.event),_stat(_t('الإيرادات'),'$_totalRevenue',Icons.attach_money)])),if(_pendingAds>0)ListTile(leading:const Icon(Icons.campaign,color:Colors.orange),title:Text('$_pendingAds ${_t('إعلان في انتظار المراجعة')}'),trailing:TextButton(onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>AdManagementScreen(providerId:FirebaseAuth.instance.currentUser?.uid,providerType:AdType.general))),child:Text(_t('مراجعة')))),Container(color:Colors.white,child:TabBar(controller:_tabController,tabs:[Tab(text:_t('الرئيسية')),Tab(text:_t('المستخدمين')),Tab(text:_t('المقدمين')),Tab(text:_t('الإعلانات'))])),Expanded(child:TabBarView(controller:_tabController,children:[_home(),_users(),_providers(),_ads()]))]));}
 Widget _stat(String l,String v,IconData i)=>Expanded(child:Column(children:[Icon(i,color:Colors.white),Text(v,style:const TextStyle(color:Colors.white,fontWeight:FontWeight.bold)),Text(l,style:const TextStyle(color:Colors.white70,fontSize:10))]));
 Widget _home()=>GridView.count(padding:const EdgeInsets.all(16),crossAxisCount:2,crossAxisSpacing:12,mainAxisSpacing:12,children:[_card(_t('المستخدمين'),'$_totalUsers',Icons.people),_card(_t('المقدمين'),'$_totalProviders',Icons.business),_card(_t('الحجوزات'),'$_totalBookings',Icons.event),_card(_t('الإيرادات'),'$_totalRevenue ${_t('ريال')}',Icons.attach_money),_card(_t('الإعلانات'),'$_pendingAds ${_t('قيد المراجعة')}',Icons.campaign),_card(_t('المنصة'),_t('نشطة'),Icons.check_circle)]);
 Widget _card(String t,String v,IconData i)=>Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Icon(i,color:AppColors.primary),const SizedBox(height:8),Text(v,style:const TextStyle(fontWeight:FontWeight.bold)),Text(t,style:const TextStyle(color:Colors.grey))])));
 Widget _users()=>StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:FirebaseFirestore.instance.collection('users').snapshots(),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());return ListView(children:s.data!.docs.map((d){final x=d.data();return ListTile(leading:const CircleAvatar(child:Icon(Icons.person)),title:Text(x['name']?.toString()??_t('مستخدم')),subtitle:Text(x['email']?.toString()??''));}).toList());});
 Widget _providers()=>DefaultTabController(length:4,child:Column(children:[const TabBar(tabs:[Tab(text:_t('أطباء')),Tab(text:_t('صيدليات')),Tab(text:_t('مختبرات')),Tab(text:_t('مستشفيات'))]),Expanded(child:TabBarView(children:[_providerList('doctors'),_providerList('pharmacies'),_providerList('labs'),_providerList('hospitals')]))]));
 Widget _providerList(String col)=>StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:FirebaseFirestore.instance.collection(col).snapshots(),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());return ListView(children:s.data!.docs.map((d)=>ListTile(leading:const Icon(Icons.business),title:Text(d.data()['name']?.toString()??_t('غير معروف')),subtitle:Text(d.data()['address']?.toString()??''))).toList());});
 Widget _ads()=>Center(child:Column(mainAxisSize:MainAxisSize.min,children:[const Icon(Icons.campaign,size:64,color:Colors.grey),const SizedBox(height:12),Text(_t('إدارة الإعلانات')),ElevatedButton(onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>const AdManagementScreen())),child:Text(_t('فتح')))]));
 @override void dispose(){_tabController.dispose();super.dispose();}
}
